$_MODULE['<{coolquotes}prestashop>coolquotes_c7234f9104ac297131f90366f1106666'] = 'Sound call';
$_MODULE['<{coolquotes}prestashop>coolquotes_d788c949668a095ee3d100b8e5c56aa2'] = 'A singing bowl struck once to invite reading. The sound is synthesised: no file is loaded. Since browsers block any sound before the visitor does something, the call only plays after their first interaction with the page, and only once per visit.';
$_MODULE['<{coolquotes}prestashop>coolquotes_90e6e4d52d335c018b287501fb9c1787'] = 'Wait before the call';
