$_MODULE['<{coolquotes}prestashop>coolquotes_f24b608b4e6f615a9b423711372bca29'] = 'Counted from the visitor\'s first interaction, to give them time to look around. From 10 to 600 seconds.';
$_MODULE['<{coolquotes}prestashop>coolquotes_7a631e47bb8a1d13a3a954f087bc3530'] = 'Music while reading';
$_MODULE['<{coolquotes}prestashop>coolquotes_0f67d7675371755c5f0b7f39066b267f'] = 'A drone and a few pentatonic notes, as long as the strip stays open. A button on the strip lets the visitor mute the sound, and their choice is kept from one page to the next.';
$_MODULE['<{coolquotes}prestashop>coolquotes_bd7a9717d29c5ddcab1bc175eda1e298'] = 'Volume';
$_MODULE['<{coolquotes}prestashop>coolquotes_9c17d29599e9e414141accb828158a8a'] = 'From 0 to 100. The module caps it at half the browser volume anyway: the aim is to invite, not to wake up.';
